sys_variable_value.value:
(function execute(inputs, outputs) {
    var score = parseFloat(inputs.fit_score) || 0;
    var actionType = 'TRIAGE_LOW_FIT_REVIEW';
    var outputSummary = 'Candidate fit score < 40 (' + score + '/100). Routed to recruiter human review queue. Automated rejection blocked by Human-in-the-Loop policy.';
    
    if (score >= 70) {
        actionType = 'TRIAGE_SHORTLIST';
        outputSummary = 'Candidate fit score >= 70 (' + score + '/100). Auto-promoted to SHORTLISTED stage and hiring manager notified.';
    } else if (score >= 40) {
        actionType = 'TRIAGE_BORDERLINE_REVIEW';
        outputSummary = 'Candidate fit score 40–69 (' + score + '/100, Borderline). Retained in recruiter review queue with targeted interview gap rubric.';
    }

    var logger = new x_snc_aegis.AEGISDecisionLogger();
    logger.logAction(
        'Resume Intelligence',
        actionType,
        inputs.app_sys_id,
        inputs.req_sys_id,
        'Evaluated 5-factor blind fit score: ' + score + '/100',
        outputSummary,
        Math.min(0.98, Math.max(0.50, 0.60 + Math.abs(score - 55) / 50)),
        'Human-in-the-Loop Governance: Terminal candidate rejections strictly reserved for human recruiters'
    );
})(inputs, outputs);

